// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

/**
 * CrossChainCrowdfund — Universal Contract for cross-chain donations
 * Follows ZetaChain Universal Contract pattern with proper gateway integration
 */

import "@zetachain/protocol-contracts/contracts/zevm/interfaces/UniversalContract.sol";
import "@zetachain/protocol-contracts/contracts/zevm/interfaces/IGatewayZEVM.sol";
import "@zetachain/protocol-contracts/contracts/zevm/interfaces/IZRC20.sol";
import { RevertContext, RevertOptions } from "@zetachain/protocol-contracts/contracts/Revert.sol";

/*//////////////////////////////////////////////////////////////
                    Minimal interfaces / utils
//////////////////////////////////////////////////////////////*/

interface IWZETA {
  function deposit() external payable;
  function withdraw(uint256 amount) external;
}

interface IUniswapV2Router02 {
  function swapExactTokensForTokens(
    uint amountIn,
    uint amountOutMin,
    address[] calldata path,
    address to,
    uint deadline
  ) external returns (uint[] memory amounts);
  function getAmountsOut(uint256 amountIn, address[] calldata path) external view returns (uint256[] memory amounts);
  function getAmountsIn(uint256 amountOut, address[] calldata path) external view returns (uint256[] memory amounts);
}

interface IERC20Minimal {
  function transfer(address to, uint256 value) external returns (bool);
  function transferFrom(address from, address to, uint256 value) external returns (bool);
  function approve(address spender, uint256 value) external returns (bool);
  function balanceOf(address) external view returns (uint256);
  function allowance(address owner, address spender) external view returns (uint256);
}

/* ---- SafeERC20-lite (no OZ) ---- */
library SafeERC20Lite {
  function safeTransfer(IERC20Minimal t, address to, uint256 v) internal {
    (bool ok, bytes memory d) = address(t).call(abi.encodeWithSelector(t.transfer.selector, to, v));
    require(ok && (d.length == 0 || abi.decode(d, (bool))), "SAFE_TRANSFER_FAIL");
  }
  function safeTransferFrom(IERC20Minimal t, address f, address to, uint256 v) internal {
    (bool ok, bytes memory d) = address(t).call(abi.encodeWithSelector(t.transferFrom.selector, f, to, v));
    require(ok && (d.length == 0 || abi.decode(d, (bool))), "SAFE_TRANSFER_FROM_FAIL");
  }
  function safeApprove(IERC20Minimal t, address s, uint256 v) internal {
    (bool ok, bytes memory d) = address(t).call(abi.encodeWithSelector(t.approve.selector, s, v));
    require(ok && (d.length == 0 || abi.decode(d, (bool))), "SAFE_APPROVE_FAIL");
  }
}

/* ---- Ownable-lite ---- */
abstract contract OwnableLite {
  address public owner;
  event OwnershipTransferred(address indexed prev, address indexed next);
  modifier onlyOwner() { require(msg.sender == owner, "ONLY_OWNER"); _; }
  constructor() { owner = msg.sender; emit OwnershipTransferred(address(0), msg.sender); }
  function transferOwnership(address n) external onlyOwner {
    require(n != address(0), "ZERO_OWNER");
    emit OwnershipTransferred(owner, n);
    owner = n;
  }
}

/* ---- ReentrancyGuard-lite ---- */
abstract contract ReentrancyGuardLite {
  uint256 private _gs = 1;
  modifier nonReentrant() { require(_gs == 1, "REENTRANCY"); _gs = 2; _; _gs = 1; }
}

/*//////////////////////////////////////////////////////////////
                          Contract
//////////////////////////////////////////////////////////////*/

contract CrossChainCrowdfund is UniversalContract, OwnableLite, ReentrancyGuardLite {
  using SafeERC20Lite for IERC20Minimal;

  /*------------------------------- TYPES -------------------------------*/

  // Creator struct removed (redundant with Campaign info)

  struct Contribution {
    uint256 campaignId;
    address donor;
    address originalToken;   // inbound zrc20 or address(0) for native in donateNative()
    address zrc20Received;   // final token delivered to creator (WZETA)
    uint256 originalAmount;
    uint256 convertedAmount;
    uint256 originChainId;
    uint64  timestamp;
    string  originChainName;
  }

  struct Campaign {
    address creator;         // ZEVM address
    address preferredZRC20;  // any whitelisted token
    bool    active;
    // Optional cross-chain payout configuration
    address payoutAddress;   // Creator's address on destination chain (EVM). If zero, pay locally on ZEVM
    uint256 payoutGasLimit;  // Gas limit to use for withdrawAndCall/call. If zero, a sane default is used
    bool    useArbitraryCall; // If true and callMessage set, use withdrawAndCall with arbitrary payload
    bytes   callMessage;     // Optional calldata for withdrawAndCall on destination chain
  }

  /*------------------------------- EVENTS -------------------------------*/

  // Public business events
  event CampaignCreated(uint256 indexed campaignId, address indexed creator, address preferredZRC20);
  event ContributionReceived(
    uint256 indexed campaignId,
    address indexed donor,
    uint256 indexed contributionId,
    address originalToken,
    uint256 originalAmount,
    uint256 convertedAmount,
    string originChain,
    string donorName,
    string note
  );

  // DEBUG events (for tracing)
  event DebugToggle(bool enabled);
  event DebugOnCallEntered(bytes originSender, uint256 originChainId, address zrc20In, uint256 amount);
  event DebugDecodedDonate(uint256 campaignId, string donorName, string note);
  event DebugDonationBegin(uint256 campaignId, address creator, address tokenIn, uint256 amountIn);
  event DebugRouterSet(address router);
  event DebugRouterMissing();
  event DebugApproveReset(address token, uint256 amount);
  event DebugApprove(address token, uint256 amount);
  event DebugSwapPlanned(address tokenIn, address tokenOut, uint256 amountIn, uint256 pathLen);
  event DebugSwapSucceeded(uint256 amountOut);
  event DebugSwapFailed(string reason);
  event DebugSwapFailedBytes(bytes lowLevelData);
  event DebugTransferOut(address token, address to, uint256 amount);
  event DebugContributionRecorded(uint256 id);
  event DebugGasFee(address token, address gasToken, uint256 gasFee, uint256 gasLimit, uint256 haveBalance);
  event DebugGatewayWithdraw(address receiverToken, uint256 amount, bool withCall);
  event DebugOnRevert(address asset, uint256 amount, bytes revertMessage);

  /*------------------------------- ERRORS -------------------------------*/

  error NotCreator();
  error CampaignInactive();
  error InvalidToken();
  error InvalidCampaign();
  error AmountZero();
  error RouterNotSet();
  error OnlySystem();
  error UnknownAction();
  error PayoutTokenNotAllowed();
  error InsufficientForGas();

  /*------------------------------ STORAGE ------------------------------*/

  address public immutable gateway;

  mapping(uint256 => Campaign) public campaigns;
  mapping(uint256 => Contribution) public contributions;

  uint256 public nextCampaignId;
  uint256 public nextContributionId;

  // Token labeling
  mapping(address => string) public tokenLabel;
  
  address public immutable WZETA;
  address public immutable ethZRC20;
  address public immutable btcZRC20;
  address public immutable usdcZRC20;

  IUniswapV2Router02 public router;

  bool public debug = true;

  // Token allowlists
  mapping(address => bool) public allowedInTokens;
  mapping(address => bool) public allowedOutTokens;
  
  event AllowedInTokenSet(address token, bool allowed);
  event AllowedOutTokenSet(address token, bool allowed);

  function setAllowedInToken(address t, bool allowed) external onlyOwner {
    require(t != address(0), "ZERO_TOKEN");
    allowedInTokens[t] = allowed;
    emit AllowedInTokenSet(t, allowed);
  }

  function setAllowedOutToken(address t, bool allowed) external onlyOwner {
    require(t != address(0), "ZERO_TOKEN");
    allowedOutTokens[t] = allowed;
    emit AllowedOutTokenSet(t, allowed);
  }

  // Slippage configuration
  uint256 public slippageBps = 300; // 3.00% default
  event SlippageUpdated(uint256 bps);
  
  function setSlippageBps(uint256 bps) external onlyOwner {
    require(bps <= 2000, "SLIPPAGE_TOO_HIGH"); // cap at 20%
    slippageBps = bps;
    emit SlippageUpdated(bps);
  }

  /*---------------------------- CONSTRUCTOR ----------------------------*/
  constructor(
    address _gateway,
    address _wzeta,
    address _ethZRC20,
    address _btcZRC20,
    address _usdcZRC20
  ) {
    if (
      _gateway == address(0) ||
      _wzeta == address(0) ||
      _ethZRC20 == address(0) ||
      _btcZRC20 == address(0)
    ) revert InvalidToken();

    gateway = _gateway;
    WZETA = _wzeta;
    ethZRC20 = _ethZRC20;
    btcZRC20 = _btcZRC20;
    usdcZRC20 = _usdcZRC20;

    tokenLabel[_ethZRC20] = "zETH.Sepolia";
    tokenLabel[_btcZRC20] = "zBTC.Sepolia";
    if (_usdcZRC20 != address(0)) tokenLabel[_usdcZRC20] = "USDC.Sepolia";
    tokenLabel[_wzeta] = "WZETA";

    // Initialize token allowlists
    allowedInTokens[_wzeta] = true;
    allowedInTokens[_ethZRC20] = true;
    allowedInTokens[_btcZRC20] = true;
    if (_usdcZRC20 != address(0)) allowedInTokens[_usdcZRC20] = true;
    allowedOutTokens[_wzeta] = true;
    allowedOutTokens[_ethZRC20] = true;
    allowedOutTokens[_btcZRC20] = true;
    if (_usdcZRC20 != address(0)) allowedOutTokens[_usdcZRC20] = true;
  }

  function setTokenLabel(address token, string calldata label) external onlyOwner {
    tokenLabel[token] = label;
  }

  /*----------------------------- ADMIN SET -----------------------------*/

  function setUniswapRouter(address _router) external onlyOwner {
    if (_router == address(0)) revert InvalidToken();
    router = IUniswapV2Router02(_router);
    if (debug) emit DebugRouterSet(_router);
  }

  function setDebug(bool enabled) external onlyOwner {
    debug = enabled;
    emit DebugToggle(enabled);
  }

  /*--------------------------- UNIVERSAL ENTRY --------------------------*/
  
  modifier onlyGateway() {
    require(msg.sender == gateway, "OnlyGateway");
    _;
  }

  /**
   * @notice Universal Contract onCall function - receives cross-chain calls
   * @param context Message context from the gateway
   * @param zrc20 The ZRC-20 token address (if any)
   * @param amount The amount of tokens received
   * @param message The encoded message data
   */
  function onCall(
      MessageContext calldata context,
      address zrc20,
      uint256 amount,
      bytes calldata message
  ) external override onlyGateway nonReentrant {
      (string memory action, bytes memory data) = abi.decode(message, (string, bytes));

      if (debug) {
          emit DebugOnCallEntered(context.sender, context.chainID, zrc20, amount);
      }

      if (keccak256(bytes(action)) == keccak256("donate_native")) {
          // For native deposits: zrc20 is the *wrapped* native (e.g. zETH) contract on ZetaChain.
          // The gateway already minted zETH to this UC.
          (uint256 campaignId, string memory donorName, string memory note) =
              abi.decode(data, (uint256, string, string));

          if (debug) emit DebugDecodedDonate(campaignId, donorName, note);

          _handleDonation(
              context,
              zrc20,        // zETH address from gateway
              amount,       // amount of zETH received
              campaignId,
              donorName,
              note
          );

      } else if (keccak256(bytes(action)) == keccak256("donate_token")) {
          // For ERC20→ZRC20 deposits
          (, , uint256 campaignId, string memory donorName, string memory note) =
              abi.decode(data, (address, uint256, uint256, string, string));

          if (debug) emit DebugDecodedDonate(campaignId, donorName, note);

          _handleDonation(
              context,
              zrc20,        // zUSDC or other ZRC20 minted on ZetaChain
              amount,       // amount of zToken received
              campaignId,
              donorName,
              note
          );

      } else {
          revert UnknownAction();
      }
  }

  /*------------------------- CAMPAIGN MANAGEMENT ------------------------*/

  // Allow any whitelisted payout token on creation
  function createCampaign(address preferredZRC20) external returns (uint256 campaignId) {
    if (preferredZRC20 == address(0)) revert InvalidToken();
    require(allowedOutTokens[preferredZRC20], "PAYOUT_TOKEN_NOT_ALLOWED");

    campaignId = ++nextCampaignId;

    // Creator tracking moved to campaigns mapping

    campaigns[campaignId] = Campaign({
      creator: msg.sender,
      preferredZRC20: preferredZRC20,
      active: true,
      payoutAddress: address(0),
      payoutGasLimit: 0,
      useArbitraryCall: false,
      callMessage: new bytes(0)
    });

    emit CampaignCreated(campaignId, msg.sender, preferredZRC20);
  }

  // Allow campaign creator to update payout token
  function updateCampaignPayoutToken(uint256 campaignId, address newToken) external {
    Campaign storage campaign = campaigns[campaignId];
    require(campaign.creator == msg.sender, "NOT_CREATOR");
    require(campaign.active, "CAMPAIGN_INACTIVE");
    require(allowedOutTokens[newToken], "PAYOUT_TOKEN_NOT_ALLOWED");

    campaign.preferredZRC20 = newToken;
    // No need to update separate creators mapping anymore

    emit CampaignCreated(campaignId, msg.sender, newToken); // Reuse event for simplicity
  }

  /// Configure destination for cross-chain payouts. If not set, payouts remain on ZEVM to creator address.
  function updateCampaignDestination(
    uint256 campaignId,
    address payoutAddress,
    uint256 payoutGasLimit
  ) external {
    Campaign storage campaign = campaigns[campaignId];
    require(campaign.creator == msg.sender, "NOT_CREATOR");
    require(campaign.active, "CAMPAIGN_INACTIVE");

    campaign.payoutAddress = payoutAddress; // zero clears cross-chain payout
    campaign.payoutGasLimit = payoutGasLimit; // zero means use default
  }

  /// Optional: set arbitrary call message to be used with withdrawAndCall on destination chain.
  function setCampaignCallMessage(
    uint256 campaignId,
    bytes calldata message,
    bool useArbitrary
  ) external {
    Campaign storage campaign = campaigns[campaignId];
    require(campaign.creator == msg.sender, "NOT_CREATOR");
    require(campaign.active, "CAMPAIGN_INACTIVE");

    campaign.callMessage = message; // empty clears
    campaign.useArbitraryCall = useArbitrary;
  }

  

  /*--------------------------- DONATION HANDLING ------------------------*/

  function _handleDonation(
    MessageContext calldata ctx,
    address zrc20In,
    uint256 amount,
    uint256 campaignId,
    string memory donorName,
    string memory note
  ) internal {
    if (amount == 0) revert AmountZero();

    Campaign storage campaign = campaigns[campaignId];
    if (campaign.creator == address(0)) revert InvalidCampaign();
    if (!campaign.active) revert CampaignInactive();

    address donorAddress = _deriveDonorAddress(ctx);

    if (debug) emit DebugDonationBegin(campaignId, campaign.creator, zrc20In, amount);

    // Handle native coin deposits vs ZRC-20 token deposits
    uint256 amountOut;
    address tokenOut;
    address actualTokenIn;

    if (zrc20In == address(0)) {
        // This branch is no longer used, but keep for safety
        revert InvalidToken();
    } else {
        // Enforce inbound token allowlist
        require(allowedInTokens[zrc20In], "TOKEN_IN_NOT_ALLOWED");
        actualTokenIn = zrc20In;
        tokenOut = campaign.preferredZRC20;
        // Enforce outbound token allowlist (in case owner changed policy after campaign creation)
        require(allowedOutTokens[tokenOut], "PAYOUT_TOKEN_NOT_ALLOWED");
        amountOut = _swapExactViaPath(actualTokenIn, tokenOut, amount);
    }

    // Payout to creator: if cross-chain destination configured, withdraw via Gateway; otherwise transfer locally on ZEVM
    _payoutCreator(campaignId, campaign, tokenOut, amountOut);

    string memory chainName = _getChainName(ctx.chainID);

    uint256 id = ++nextContributionId;
    contributions[id] = Contribution({
      campaignId: campaignId,
      donor: donorAddress,
      originalToken: actualTokenIn,
      zrc20Received: tokenOut,
      originalAmount: amount,
      convertedAmount: amountOut,
      originChainId: ctx.chainID,
      timestamp: uint64(block.timestamp),
      originChainName: chainName
    });

    if (debug) emit DebugContributionRecorded(id);

    emit ContributionReceived(
      campaignId,
      donorAddress,
      id,
      actualTokenIn,
      amount,
      amountOut,
      chainName,
      donorName,
      note
    );
  }

  /// Accept native ZETA, wrap to WZETA, and forward immediately (no escrow)
  function donateNative(
    uint256 campaignId,
    string calldata donorName,
    string calldata note
  ) external payable nonReentrant {
    require(msg.value > 0, "NO_VALUE");

    Campaign storage c = campaigns[campaignId];
    if (c.creator == address(0)) revert InvalidCampaign();
    if (!c.active) revert CampaignInactive();

    IWZETA(WZETA).deposit{ value: msg.value }(); // wrap ZETA -> WZETA

    // Enforce allowlists
    require(allowedInTokens[WZETA], "TOKEN_IN_NOT_ALLOWED");
    address tokenOut = c.preferredZRC20;
    require(allowedOutTokens[tokenOut], "PAYOUT_TOKEN_NOT_ALLOWED");
    uint256 converted = _swapExactViaPath(WZETA, tokenOut, msg.value);

    _payoutCreator(campaignId, c, tokenOut, converted);

    uint256 id = ++nextContributionId;
    contributions[id] = Contribution({
      campaignId: campaignId,
      donor: msg.sender,
      originalToken: address(0),
      zrc20Received: tokenOut,
      originalAmount: msg.value,
      convertedAmount: converted,
      originChainId: block.chainid,
      timestamp: uint64(block.timestamp),
      originChainName: "ZetaChain"
    });

    if (debug) emit DebugContributionRecorded(id);

    emit ContributionReceived(
      campaignId,
      msg.sender,
      id,
      address(0),
      msg.value,
      converted,
      "ZetaChain",
      donorName,
      note
    );
  }

  /// Accept local ZRC-20 and forward (swap->WZETA->creator)
  function donateZRC20(
    address token,
    uint256 amount,
    uint256 campaignId,
    string calldata donorName,
    string calldata note
  ) external nonReentrant {
    require(amount > 0, "NO_AMOUNT");
    if (!allowedInTokens[token]) revert InvalidToken();

    Campaign storage c = campaigns[campaignId];
    if (c.creator == address(0)) revert InvalidCampaign();
    if (!c.active) revert CampaignInactive();

    IERC20Minimal(token).safeTransferFrom(msg.sender, address(this), amount);

    address tokenOut = c.preferredZRC20;
    require(allowedOutTokens[tokenOut], "PAYOUT_TOKEN_NOT_ALLOWED");
    uint256 converted = _swapExactViaPath(token, tokenOut, amount);

    _payoutCreator(campaignId, c, tokenOut, converted);

    string memory chainName = bytes(tokenLabel[token]).length == 0
      ? "ZetaChain"
      : tokenLabel[token];

    uint256 id = ++nextContributionId;
    contributions[id] = Contribution({
      campaignId: campaignId,
      donor: msg.sender,
      originalToken: token,
      zrc20Received: tokenOut,
      originalAmount: amount,
      convertedAmount: converted,
      originChainId: block.chainid,
      timestamp: uint64(block.timestamp),
      originChainName: chainName
    });

    if (debug) emit DebugContributionRecorded(id);

    emit ContributionReceived(
      campaignId,
      msg.sender,
      id,
      token,
      amount,
      converted,
      chainName,
      donorName,
      note
    );
  }

  /*--------------------------- RESCUE FUNCTIONS --------------------------*/
  
  event Rescue(address indexed token, address indexed to, uint256 amount);
  
  function rescueToken(address token, address to, uint256 amount) external onlyOwner {
    IERC20Minimal(token).safeTransfer(to, amount);
    emit Rescue(token, to, amount);
  }

  function rescueNative(address to, uint256 amount) external onlyOwner {
    payable(to).transfer(amount);
    emit Rescue(address(0), to, amount);
  }

  /*------------------------------ SWAPPING ------------------------------*/

  function _swapExactViaPath(
    address tokenIn,
    address tokenOut,
    uint256 amountIn
  ) internal returns (uint256 amountOut) {
    if (tokenIn == tokenOut) return amountIn;
    if (address(router) == address(0)) {
      if (debug) emit DebugRouterMissing();
      revert RouterNotSet();
    }

    // Get quoted amount out
    address[] memory path;
    if (tokenIn != WZETA && tokenOut != WZETA) {
      path = new address[](3);
      path[0] = tokenIn;
      path[1] = WZETA;
      path[2] = tokenOut;
    } else {
      path = new address[](2);
      path[0] = tokenIn;
      path[1] = tokenOut;
    }
    
    uint[] memory quotes = router.getAmountsOut(amountIn, path);
    uint256 minOut = (quotes[quotes.length - 1] * (10_000 - slippageBps)) / 10_000;

    if (debug) emit DebugApproveReset(tokenIn, 0);
    IERC20Minimal(tokenIn).safeApprove(address(router), 0);
    if (debug) emit DebugApprove(tokenIn, amountIn);
    IERC20Minimal(tokenIn).safeApprove(address(router), amountIn);

    if (debug) emit DebugSwapPlanned(tokenIn, tokenOut, amountIn, path.length);

    try router.swapExactTokensForTokens(
      amountIn,
      minOut, // Use calculated slippage protection
      path,
      address(this),
      block.timestamp + 600
    ) returns (uint[] memory returnAmounts) {
      amountOut = returnAmounts[returnAmounts.length - 1];
      if (debug) emit DebugSwapSucceeded(amountOut);
      
      // Clean up approval after swap
      IERC20Minimal(tokenIn).safeApprove(address(router), 0);
    } catch Error(string memory reason) {
      if (debug) emit DebugSwapFailed(reason);
      revert(reason);
    } catch (bytes memory lowLevelData) {
      if (debug) emit DebugSwapFailedBytes(lowLevelData);
      revert("SWAP_FAILED");
    }
  }

  /*------------------------------ PAYOUT -------------------------------*/

  function _payoutCreator(
    uint256 campaignId,
    Campaign storage campaign,
    address tokenOut,
    uint256 amountOut
  ) internal {
    if (campaign.payoutAddress == address(0)) {
      // Local payout on ZEVM
      IERC20Minimal(tokenOut).safeTransfer(campaign.creator, amountOut);
      if (debug) emit DebugTransferOut(tokenOut, campaign.creator, amountOut);
      return;
    }

    // Cross-chain payout via Gateway
    uint256 gasLimit = campaign.payoutGasLimit == 0 ? 200_000 : campaign.payoutGasLimit;

    // Quote gas fee and gas ZRC-20 for this withdrawal
    (address gasZRC20, uint256 gasFee) = IZRC20(tokenOut).withdrawGasFeeWithGasLimit(gasLimit);

    // Ensure we have enough gasZRC20 to cover fee; swap from tokenOut if needed
    uint256 have = IERC20Minimal(gasZRC20).balanceOf(address(this));
    if (have < gasFee) {
      uint256 shortfall = gasFee - have;
      if (tokenOut == gasZRC20) {
        // No swap needed; reserve from amountOut directly
        if (amountOut <= shortfall) revert InsufficientForGas();
        amountOut -= shortfall;
      } else {
        // Swap a portion of tokenOut to gasZRC20 to cover fee
        uint256 used = _swapToCoverGasFee(tokenOut, gasZRC20, shortfall, amountOut);
        amountOut -= used;
      }
    }

    if (debug) emit DebugGasFee(tokenOut, gasZRC20, gasFee, gasLimit, IERC20Minimal(gasZRC20).balanceOf(address(this)));

    if (amountOut == 0) revert InsufficientForGas();

    // Approvals for gateway
    if (gasZRC20 == tokenOut) {
      // Approve once for both withdraw amount and gas fee
      IERC20Minimal(tokenOut).safeApprove(gateway, 0);
      IERC20Minimal(tokenOut).safeApprove(gateway, amountOut + gasFee);
    } else {
      IERC20Minimal(gasZRC20).safeApprove(gateway, 0);
      IERC20Minimal(gasZRC20).safeApprove(gateway, gasFee);
      IERC20Minimal(tokenOut).safeApprove(gateway, 0);
      IERC20Minimal(tokenOut).safeApprove(gateway, amountOut);
    }

    bytes memory receiver = abi.encodePacked(campaign.payoutAddress);

    if (campaign.callMessage.length > 0 || campaign.useArbitraryCall) {
      CallOptions memory co = CallOptions({
        gasLimit: gasLimit,
        isArbitraryCall: campaign.useArbitraryCall
      });
      RevertOptions memory ro = RevertOptions({
        revertAddress: address(this),
        callOnRevert: true,
        abortAddress: address(0),
        revertMessage: abi.encode(campaignId, tokenOut, amountOut),
        onRevertGasLimit: gasLimit
      });
      IGatewayZEVM(gateway).withdrawAndCall(
        receiver,
        amountOut,
        tokenOut,
        campaign.callMessage,
        co,
        ro
      );
      if (debug) emit DebugGatewayWithdraw(tokenOut, amountOut, true);
    } else {
      RevertOptions memory ro2 = RevertOptions({
        revertAddress: address(this),
        callOnRevert: true,
        abortAddress: address(0),
        revertMessage: abi.encode(campaignId, tokenOut, amountOut),
        onRevertGasLimit: gasLimit
      });
      IGatewayZEVM(gateway).withdraw(
        receiver,
        amountOut,
        tokenOut,
        ro2
      );
      if (debug) emit DebugGatewayWithdraw(tokenOut, amountOut, false);
    }
  }

  function _swapToCoverGasFee(
    address tokenIn,
    address gasToken,
    uint256 neededGasTokenOut,
    uint256 maxInputAvailable
  ) internal returns (uint256 usedInput) {
    if (address(router) == address(0)) revert RouterNotSet();

    // Build path tokenIn -> (WZETA) -> gasToken
    address[] memory path;
    if (tokenIn != WZETA && gasToken != WZETA) {
      path = new address[](3);
      path[0] = tokenIn;
      path[1] = WZETA;
      path[2] = gasToken;
    } else {
      path = new address[](2);
      path[0] = tokenIn;
      path[1] = gasToken;
    }

    uint[] memory amountsIn = router.getAmountsIn(neededGasTokenOut, path);
    uint256 requiredIn = amountsIn[0];
    // Add slippage buffer
    uint256 amountIn = (requiredIn * (10_000 + slippageBps)) / 10_000;
    if (amountIn > maxInputAvailable) revert InsufficientForGas();

    if (debug) emit DebugApproveReset(tokenIn, 0);
    IERC20Minimal(tokenIn).safeApprove(address(router), 0);
    if (debug) emit DebugApprove(tokenIn, amountIn);
    IERC20Minimal(tokenIn).safeApprove(address(router), amountIn);

    // Swap exact input to get at least neededGasTokenOut
    router.swapExactTokensForTokens(
      amountIn,
      neededGasTokenOut,
      path,
      address(this),
      block.timestamp + 600
    );

    // Clean up approval
    IERC20Minimal(tokenIn).safeApprove(address(router), 0);

    return amountIn;
  }

  /*------------------------------ VIEW FUNCTIONS -------------------------------*/

  struct CampaignInfo {
    uint256 campaignId;
    address creator;
    address preferredZRC20;
    bool active;
  }

  /**
   * @notice Get all synced campaigns - optimized view function for faster matching
   * @dev Returns campaign data in batches to avoid gas limits
   * @param startId Starting campaign ID (use 1 for first batch)
   * @param limit Maximum number of campaigns to return (max 100)
   * @return infos Array of campaign info
   * @return nextStart Next starting ID for pagination (0 if no more)
   */
  function getAllSyncedCampaigns(uint256 startId, uint256 limit) 
    external 
    view 
    returns (CampaignInfo[] memory infos, uint256 nextStart) 
  {
    require(limit > 0 && limit <= 100, "INVALID_LIMIT");
    require(startId > 0, "INVALID_START_ID");
    
    uint256 totalCampaigns = nextCampaignId;
    uint256 remainingCampaigns = totalCampaigns >= startId ? totalCampaigns - startId + 1 : 0;
    uint256 batchSize = remainingCampaigns > limit ? limit : remainingCampaigns;
    
    infos = new CampaignInfo[](batchSize);
    uint256 count = 0;
    
    for (uint256 i = startId; i <= totalCampaigns && count < limit; i++) {
      Campaign storage c = campaigns[i];
      if (c.creator != address(0)) {
        infos[count] = CampaignInfo({
          campaignId: i,
          creator: c.creator,
          preferredZRC20: c.preferredZRC20,
          active: c.active
        });
        count++;
      }
    }
    
    // Resize array if needed
    if (count < batchSize) {
      CampaignInfo[] memory resized = new CampaignInfo[](count);
      for (uint256 i = 0; i < count; i++) {
        resized[i] = infos[i];
      }
      infos = resized;
    }
    
    // Calculate next start for pagination
    nextStart = (startId + limit <= totalCampaigns) ? startId + limit : 0;
  }

  /**
   * @notice Get specific campaign information
   * @param campaignId The campaign ID to query
   * @return info Campaign information struct
   */
  function getCampaignInfo(uint256 campaignId) external view returns (CampaignInfo memory info) {
    Campaign storage campaign = campaigns[campaignId];
    require(campaign.creator != address(0), "CAMPAIGN_NOT_FOUND");
    
    info = CampaignInfo({
      campaignId: campaignId,
      creator: campaign.creator,
      preferredZRC20: campaign.preferredZRC20,
      active: campaign.active
    });
  }

  /**
   * @notice Check if a campaign exists and is active
   * @param campaignId The campaign ID to check
   * @return exists Whether the campaign exists
   * @return active Whether the campaign is active
   */
  function campaignStatus(uint256 campaignId) external view returns (bool exists, bool active) {
    Campaign storage campaign = campaigns[campaignId];
    exists = campaign.creator != address(0);
    active = exists && campaign.active;
  }

  /*------------------------------ HELPERS -------------------------------*/

  function _deriveDonorAddress(MessageContext calldata ctx) internal pure returns (address) {
    // ctx.sender is bytes (origin address payload). Derive a stable pseudo-address for logs/accounting.
    return address(uint160(uint256(keccak256(abi.encodePacked(ctx.sender, ctx.chainID)))));
  }

  function _getChainName(uint256 chainId) internal pure returns (string memory) {
    if (chainId == 11155111) return "Ethereum Sepolia";
    if (chainId == 80001) return "Polygon Mumbai";
    if (chainId == 97) return "BSC Testnet";
    if (chainId == 7001) return "ZetaChain Athens";
    return "Unknown Chain";
  }

  /*------------------------------ REVERT HANDLER -------------------------------*/
  function onRevert(RevertContext calldata revertContext) external onlyGateway {
    if (debug) emit DebugOnRevert(revertContext.asset, revertContext.amount, revertContext.revertMessage);
    // Attempt fallback payout to campaign creator using encoded revert message
    (uint256 campaignId) = abi.decode(
      revertContext.revertMessage,
      (uint256)
    );
    Campaign storage c = campaigns[campaignId];
    if (c.creator != address(0)) {
      IERC20Minimal(revertContext.asset).safeTransfer(c.creator, revertContext.amount);
      if (debug) emit DebugTransferOut(revertContext.asset, c.creator, revertContext.amount);
    }
  }

  /// Reject plain native transfers — must call donateNative()
  receive() external payable {
    revert("USE_DONATE_NATIVE");
  }
}

contracts/GiveHubUniversal.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import "@zetachain/protocol-contracts/contracts/zevm/interfaces/UniversalContract.sol";
import "@zetachain/protocol-contracts/contracts/zevm/interfaces/IGatewayZEVM.sol";
import "@zetachain/protocol-contracts/contracts/zevm/interfaces/IZRC20.sol";
import { RevertContext, RevertOptions } from "@zetachain/protocol-contracts/contracts/Revert.sol";

/* ---- ReentrancyGuard-lite ---- */
abstract contract ReentrancyGuardLite {
    uint256 private _gs = 1;
    modifier nonReentrant() { require(_gs == 1, "REENTRANCY"); _gs = 2; _; _gs = 1; }
}

contract GiveHubUniversal is UniversalContract, ReentrancyGuardLite {
    IGatewayZEVM public immutable gateway;

    struct Campaign {
        uint256 id;
        address creator;
        address payoutToken; // ZRC20 token address for payouts
        uint256 payoutChainId; // Chain ID where creator wants to receive funds
        address payoutAddress; // Creator's address on the payout chain
        uint256 raised;
        uint256 goal;
        bool active;
    }

    struct Contribution {
        uint256 campaignId;
        address donor;
        uint256 amount;
        address token;
        string originChain;
        uint256 timestamp;
    }

    mapping(uint256 => Campaign) public campaigns;
    mapping(uint256 => Contribution[]) public campaignContributions;
    uint256 public nextCampaignId = 1;

    event CampaignCreated(
        uint256 indexed campaignId,
        address indexed creator,
        uint256 goal,
        address payoutToken,
        uint256 payoutChainId,
        address payoutAddress
    );

    event ContributionReceived(
        uint256 indexed campaignId,
        address indexed donor,
        uint256 indexed contributionId,
        address originalToken,
        uint256 originalAmount,
        uint256 convertedAmount,
        string originChain,
        string donorName,
        string note
    );

    event PayoutInitiated(
        uint256 indexed campaignId,
        address indexed creator,
        uint256 amount,
        uint256 destinationChainId,
        address destinationAddress
    );

    constructor(address _gateway) {
        gateway = IGatewayZEVM(_gateway);
    }

    /**
     * @dev Creates a new campaign with cross-chain payout configuration
     */
    function createCampaign(
        uint256 _goal,
        address _payoutToken,
        uint256 _payoutChainId,
        address _payoutAddress
    ) external returns (uint256) {
        uint256 campaignId = nextCampaignId++;

        campaigns[campaignId] = Campaign({
            id: campaignId,
            creator: msg.sender,
            payoutToken: _payoutToken,
            payoutChainId: _payoutChainId,
            payoutAddress: _payoutAddress,
            raised: 0,
            goal: _goal,
            active: true
        });

        emit CampaignCreated(
            campaignId,
            msg.sender,
            _goal,
            _payoutToken,
            _payoutChainId,
            _payoutAddress
        );

        return campaignId;
    }

    /**
     * @dev Called when receiving cross-chain donations via Gateway
     */
    function onCall(
        MessageContext calldata context,
        address zrc20,
        uint256 amount,
        bytes calldata message
    ) external override nonReentrant {
        require(msg.sender == address(gateway), "Only gateway can call");

        // Decode the message to get campaign details
        (uint256 campaignId, string memory donorName, string memory note) = 
            abi.decode(message, (uint256, string, string));

        Campaign storage campaign = campaigns[campaignId];
        require(campaign.active, "Campaign not active");

        // Update campaign raised amount
        campaign.raised += amount;

        // Derive a pseudo-address for donor from cross-chain context
        address donorAddr = _deriveDonorAddress(context);

        // Store contribution
        campaignContributions[campaignId].push(Contribution({
            campaignId: campaignId,
            donor: donorAddr,
            amount: amount,
            token: zrc20,
            originChain: getChainName(context.chainID),
            timestamp: block.timestamp
        }));

        emit ContributionReceived(
            campaignId,
            donorAddr,
            campaignContributions[campaignId].length - 1,
            zrc20,
            amount,
            amount,
            getChainName(context.chainID),
            donorName,
            note
        );
    }

    /**
     * @dev Initiates payout to creator's chosen chain
     */
    function withdrawToCreator(uint256 campaignId) external nonReentrant {
        Campaign storage campaign = campaigns[campaignId];
        require(msg.sender == campaign.creator, "Only creator can withdraw");
        require(campaign.raised > 0, "No funds to withdraw");

        uint256 amount = campaign.raised;
        campaign.raised = 0;

        // Get the ZRC20 token for payout
        IZRC20 payoutToken = IZRC20(campaign.payoutToken);

        // Calculate gas fee and require gas token equals payout token (no swap logic here)
        uint256 gasLimit = 200000;
        (address gasZRC20, uint256 gasFee) = payoutToken.withdrawGasFeeWithGasLimit(gasLimit);
        require(gasZRC20 == campaign.payoutToken, "GAS_TOKEN_MISMATCH");
        require(amount > gasFee, "Amount too small to cover gas");

        uint256 withdrawAmount = amount - gasFee;

        // Approve gateway to spend tokens (both withdraw amount and gas fee)
        payoutToken.approve(address(gateway), 0);
        payoutToken.approve(address(gateway), withdrawAmount + gasFee);

        // Initiate cross-chain withdrawal
        gateway.withdraw(
            abi.encodePacked(campaign.payoutAddress),
            withdrawAmount,
            campaign.payoutToken,
            RevertOptions({
                revertAddress: address(this),
                callOnRevert: true,
                abortAddress: address(0),
                revertMessage: abi.encode(campaignId),
                onRevertGasLimit: gasLimit
            })
        );

        emit PayoutInitiated(
            campaignId,
            campaign.creator,
            withdrawAmount,
            campaign.payoutChainId,
            campaign.payoutAddress
        );
    }

    /**
     * @dev Direct donation in ZRC20 tokens (already on ZetaChain)
     */
    function donateDirectly(
        uint256 campaignId,
        address zrc20Token,
        uint256 amount,
        string memory donorName,
        string memory note
    ) external nonReentrant {
        Campaign storage campaign = campaigns[campaignId];
        require(campaign.active, "Campaign not active");

        // Transfer tokens from donor
        IZRC20(zrc20Token).transferFrom(msg.sender, address(this), amount);

        // Update campaign
        campaign.raised += amount;

        // Store contribution
        campaignContributions[campaignId].push(Contribution({
            campaignId: campaignId,
            donor: msg.sender,
            amount: amount,
            token: zrc20Token,
            originChain: "ZetaChain",
            timestamp: block.timestamp
        }));

        emit ContributionReceived(
            campaignId,
            msg.sender,
            campaignContributions[campaignId].length - 1,
            zrc20Token,
            amount,
            amount,
            "ZetaChain",
            donorName,
            note
        );
    }

    /**
     * @dev Updates campaign payout configuration
     */
    function updatePayoutConfig(
        uint256 campaignId,
        address newPayoutToken,
        uint256 newPayoutChainId,
        address newPayoutAddress
    ) external {
        Campaign storage campaign = campaigns[campaignId];
        require(msg.sender == campaign.creator, "Only creator can update");

        campaign.payoutToken = newPayoutToken;
        campaign.payoutChainId = newPayoutChainId;
        campaign.payoutAddress = newPayoutAddress;
    }

    /**
     * @dev Closes a campaign
     */
    function closeCampaign(uint256 campaignId) external {
        Campaign storage campaign = campaigns[campaignId];
        require(msg.sender == campaign.creator, "Only creator can close");
        campaign.active = false;
    }

    /**
     * @dev Helper to get chain name from chain ID
     */
    function getChainName(uint256 chainId) internal pure returns (string memory) {
        if (chainId == 1) return "Ethereum";
        if (chainId == 56) return "BSC";
        if (chainId == 137) return "Polygon";
        if (chainId == 11155111) return "Sepolia";
        if (chainId == 7001) return "ZetaChain";
        if (chainId == 901) return "Solana";
        if (chainId == 18332) return "Bitcoin";
        return "Unknown";
    }

    // Derive a stable pseudo-address for logs/accounting from cross-chain context
    function _deriveDonorAddress(MessageContext calldata ctx) internal pure returns (address) {
        return address(uint160(uint256(keccak256(abi.encodePacked(ctx.sender, ctx.chainID)))));
    }

    /**
     * @dev Get campaign details
     */
    function getCampaign(uint256 campaignId) external view returns (Campaign memory) {
        return campaigns[campaignId];
    }

    /**
     * @dev Get contributions for a campaign
     */
    function getContributions(uint256 campaignId) external view returns (Contribution[] memory) {
        return campaignContributions[campaignId];
    }

    /**
     * @dev Fallback handler for cross-chain payout reverts. Sends the returned funds to the campaign creator.
     */
    function onRevert(RevertContext calldata revertContext) external {
        require(msg.sender == address(gateway), "Only gateway can call");
        // We encoded only campaignId in revert message
        (uint256 campaignId) = abi.decode(revertContext.revertMessage, (uint256));
        Campaign storage campaign = campaigns[campaignId];
        if (campaign.creator != address(0)) {
            // Transfer returned asset back to campaign creator on ZEVM
            IZRC20(revertContext.asset).transfer(campaign.creator, revertContext.amount);
        }
    }
}

